"use strict";(globalThis.webpackChunkgrc||=[]).push([[50718],{91665(e){e.exports=JSON.parse('{"citeKey":"wu2006gridharvest","slug":"wu-2006-grid-harvest-5ba8","title":"Grid Harvest Service: A Performance System of Grid Computing","authors":["M. Wu","X.-H. Sun"],"venue":"Journal of Parallel and Distributed Computing, vol. 66, no. 10, pp. 1322-1337, 2006. (ACM Computing Review)","type":"Journal","entryType":"article","date":"January, 2006","year":2006,"era":"iit","month":1,"doi":"10.1016/j.jpdc.2006.05.008","abstract":"Conventional performance evaluation mechanisms focus on dedicated systems. Grid computing infrastructure, on the other hand, is a shared collaborative environment constructed on virtual organizations. Each organization has its own resource management policy and usage pattern. The non-dedicated characteristic of Grid computing prevents the leverage of conventional performance evaluation systems. In this study, we introduce the grid harvest service (GHS) performance evaluation and task scheduling system for solving large-scale applications in a shared environment. GHS is based on a novel performance prediction model and a set of task scheduling algorithms. GHS supports three classes of task scheduling, single task, parallel processing and meta-task. Experimental results show that GHS provides a satisfactory solution for performance prediction and task scheduling of large applications and has a real potential.","hasAbstract":true,"lede":"In this study, we introduce the grid harvest service (GHS) performance evaluation and task scheduling system for solving large-scale applications in a shared environment.","links":{"pdf":"https://grc.iit.edu/papers/2006/wu-2006-grid-harvest-5ba8.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);